/* V8 full knowledge preview: hierarchical navigation, 90 lessons, 88 components, 6 scenes. */
(() => {
'use strict';
const STORAGE='adFactoryLearning.v8.layout-qa';
const BEFORE_MIGRATION=STORAGE+'.before-migration';
const OFFICIAL_STORAGE='adFactoryLearning.v2';
const $=(q,root=document)=>root.querySelector(q);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const h=(x)=>esc(x);
const clamp=(v,min,max)=>Math.min(max,Math.max(min,v));
let db=null, route='', priorRoute='', activeOverlay=null, overlayTrigger=null, toastTimeout=0, lastComponentListRoute='/components';
const routeY={};
const baseState={done:Array.from({length:48},(_,i)=>i+1),favorites:[],notes:{},quiz:{},review:[],wrong:[],recent:[],lastLesson:49,lessonTab:'explain',componentTabs:{},sceneForms:{customers:{name:'',phone:''},quotes:{name:'无边发光字',width:'40',height:'20',qty:'2',price:'240'}},sceneCustomers:[],sceneStock:[{name:'亚克力板',qty:28},{name:'不锈钢板',qty:14},{name:'LED 模组',qty:430}],sceneProduction:[{id:'D-101',name:'瑞冠口腔',status:'待排版'},{id:'D-102',name:'悦己瑜伽',status:'生产中'}],sceneOrders:[{id:'A-1028',customer:'天悦广告',status:'生产中',amount:'¥2,860'},{id:'A-1029',customer:'瑞冠口腔',status:'待生产',amount:'¥1,540'},{id:'A-1030',customer:'悦己瑜伽',status:'已完成',amount:'¥980'}]};
function initState(){try{let old=JSON.parse(localStorage.getItem(STORAGE)||'null');if(old&&typeof old==='object'){
 const st={...baseState,...old};for(let k of ['done','favorites','review','wrong','recent'])if(!Array.isArray(st[k]))st[k]=[];if(!st.notes||typeof st.notes!=='object')st.notes={};if(!st.quiz||typeof st.quiz!=='object')st.quiz={};if(!st.sceneForms||typeof st.sceneForms!=='object')st.sceneForms=structuredCloneSafe(baseState.sceneForms);if(!Array.isArray(st.sceneCustomers))st.sceneCustomers=[];return st;
}}catch(e){}return structuredCloneSafe(baseState)}
function structuredCloneSafe(v){return JSON.parse(JSON.stringify(v))}

function cleanLessonIds(a){return Array.isArray(a)?[...new Set(a.filter(n=>Number.isInteger(n)&&n>=1&&n<=90))]:[]}
function readOfficialProgress(){
 try{const raw=localStorage.getItem(OFFICIAL_STORAGE);if(!raw)return null;
 const x=JSON.parse(raw);return x&&typeof x==='object'&&Array.isArray(x.done)?x:null;}catch(e){return null}
}
function importOfficialProgress(){
 const old=readOfficialProgress();
 if(!old){notify('没有找到当前浏览器的正式版记录，请从正式版导出 JSON，再在此导入。');return}
 const dones=cleanLessonIds(old.done),bookmarks=cleanLessonIds(old.bookmarks);
 const notes=old.notes&&typeof old.notes==='object'&&!Array.isArray(old.notes)?old.notes:{};
 const noteCount=Object.entries(notes).filter(([k,v])=>Number(k)>=1&&Number(k)<=90&&typeof v==='string'&&v.trim()).length;
 if(!confirm('发现正式版记录：掌握 '+dones.length+' 课，笔记 '+noteCount+' 篇，收藏 '+bookmarks.length+' 项。\n确认合并到 V8 验收版？旧记录不会修改，合并前自动保存 V8 回退点。'))return;
 try{
  localStorage.setItem(BEFORE_MIGRATION,JSON.stringify(state));
  const next=structuredCloneSafe(state);
  next.done=cleanLessonIds([...next.done,...dones]);
  next.review=cleanLessonIds([...(next.review||[]),...cleanLessonIds(old.review)]);
  next.wrong=cleanLessonIds([...(next.wrong||[]),...cleanLessonIds(old.wrong)]);
  next.favorites=[...new Set([...next.favorites,...bookmarks.map(id=>'lesson:'+id)])];
  for(const [id,value] of Object.entries(notes)){if(!/^\d+$/.test(id)||Number(id)<1||Number(id)>90||typeof value!=='string')continue;
   if(!String(next.notes[id]||'').trim())next.notes[id]=value.slice(0,10000);}
  const quizzes=old.quiz&&typeof old.quiz==='object'&&!Array.isArray(old.quiz)?old.quiz:{};
  for(const [id,value] of Object.entries(quizzes)){if(!/^\d+$/.test(id)||Number(id)<1||Number(id)>90||!Number.isInteger(value)||value<0||value>2||next.quiz[id])continue;
   const l=findLesson(id);if(l)next.quiz[id]={value,correct:l.a===value};}
  if(state.lastLesson===49&&Number.isInteger(Number(old.lastLesson))&&Number(old.lastLesson)>=1&&Number(old.lastLesson)<=90)next.lastLesson=Number(old.lastLesson);
  state=next;
  if(!persist())throw Error('本地保存失败');
  nav('/me/data');notify('学习记录已合并到 V8，正式版未修改');
 }catch(e){notify('迁移未完成：'+e.message)}
}
function restoreBeforeMigration(){
 try{
  const raw=localStorage.getItem(BEFORE_MIGRATION);if(!raw){notify('没有可恢复的迁移前记录');return}
  const x=JSON.parse(raw);if(!x||!Array.isArray(x.done)||!Array.isArray(x.favorites)||!x.notes||typeof x.notes!=='object')throw Error('回退记录格式错误');
  if(!confirm('恢复合并前的 V8 测试记录？后续修改将被覆盖。'))return;
  state={...structuredCloneSafe(baseState),...x};persist();nav('/me/data');notify('已恢复迁移前的 V8 记录');
 }catch(e){notify('恢复失败：'+e.message)}
}

let state=initState();
let filters={lesson:'',component:'',componentCat:'all',categoryIds:{},orders:'all',orderQuery:'',global:''};
function persist(){try{localStorage.setItem(STORAGE,JSON.stringify(state));return true}catch(e){notify('本浏览器未允许保存。可在“我的”中导出数据。');return false}}
function notify(msg){const el=$('#toast');el.textContent=msg;el.classList.add('visible');clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>el.classList.remove('visible'),2800)}
const path=()=>{let p=decodeURI((location.hash||'#/home').slice(1));return p.startsWith('/')?p:'/home'};
function nav(to){if(path()===to){route=to;render();return}routeY[route]=window.scrollY;location.hash='#'+to}
const encoded=(value)=>encodeURIComponent(value);
const link=(to,label,extra='')=>`<a href="#${h(to)}" ${extra}>${label}</a>`;
function breadcrumb(items){return `<div class="breadcrumb">${items.map((it,i)=>i===items.length-1?`<span class="now">${h(it[0])}</span>`:`<button type="button" data-go="${h(it[1])}">${h(it[0])}</button><span>›</span>`).join('')}</div>`}
function back(to,label='返回上一级'){return `<button type="button" class="back-link" data-go="${h(to)}"><span aria-hidden="true">←</span> ${h(label)}</button>`}
function head(title,subtitle='',right=''){return `<header class="page-head"><div><h1>${h(title)}</h1>${subtitle?`<p class="subtitle">${h(subtitle)}</p>`:''}</div>${right}</header>`}
function row(to,title,desc='',meta='',ico='›'){return `<a href="#${h(to)}" class="list-row"><span class="row-icon" aria-hidden="true">${ico}</span><span class="row-body"><span class="row-title">${h(title)}</span>${desc?`<div class="row-desc">${h(desc)}</div>`:''}</span>${meta?`<span class="row-indicator">${h(meta)}</span>`:''}<span class="row-arrow">›</span></a>`}
function iconFor(cat){return {Layout:'▦',Content:'▤',Form:'▥',Interaction:'◫',State:'●',Visual:'◈',Motion:'◌',Business:'▧',Accessibility:'◎',Workflow:'↝'}[cat]||'◈'}
function findLesson(n){return db.lessons.find(x=>x.id===Number(n))}
function findComponent(id){return db.components.find(x=>x.id===id)}
function findScene(id){return db.scenes.find(x=>x.id===id)}
function recent(type,id){const key=`${type}:${id}`;state.recent=[key,...state.recent.filter(x=>x!==key)].slice(0,8);persist()}
function section(title,linkTo='',action='查看全部'){return `<div class="section-head"><h2>${h(title)}</h2>${linkTo?link(linkTo,h(action),'class="text-link"'):''}</div>`}
function home(){const done=state.done.filter(x=>x>=1&&x<=90).length;const l=findLesson(state.lastLesson)||findLesson(49);const recentItems=state.recent.slice(0,4).map(r=>{let [type,id]=r.split(':');if(type==='lesson'){let x=findLesson(id);return x?row(`/learn/lesson/${x.id}`,`第 ${x.id} 课 · ${x.title}`,'课程','最近查看','▤'):''}if(type==='component'){let x=findComponent(id);return x?row(`/components/detail/${x.id}`,x.name,'组件','最近查看','◫'):''}let x=findScene(id);return x?row(`/practice/scenario/${x.id}`,x.title,'ERP 场景','最近查看','▧'):''}).filter(Boolean);
return `<div class="page-enter">${head('今天学什么','把复杂知识拆成一个个可操作的小任务。')}<div class="home-hero"><section class="hero-main"><div><div class="hero-label">CONTINUE · 继续学习</div><h2>第 ${l.id} 课 · ${h(l.title)}</h2><p>已掌握 ${done} / 90 课</p></div>${link(`/learn/lesson/${l.id}`,'继续学习 →','class="btn btn-light"')}</section><section class="card hero-side"><div><div class="eyebrow">学习进度</div><div class="stat-val">${done}<span style="font-size:16px;color:#7a899d;font-weight:600"> / 90</span></div><div class="progressbar"><span style="width:${done/90*100}%"></span></div></div></section></div>${section('探索')}<div class="card-grid">${[['learn','▤','学习','90 节课程 · 13 阶段'],['components','◫','组件','88 个可演示组件'],['practice','▧','实战','6 个 ERP 业务场景']].map(([id,ic,n,d])=>`<a href="#/${id}" class="card module-card clickable"><span class="module-icon">${ic}</span><strong>${n}</strong><p>${d}</p><span class="arrow">↗</span></a>`).join('')}</div>${section('最近查看')}${recentItems.length?`<div class="card list-card">${recentItems.join('')}</div>`:`<div class="card list-card">${row('/learn/lesson/49','第 49 课 · 数据库','从上次学习继续','','▤')}${row('/components/detail/modal','Modal 弹窗','直接体验组件 Demo','','◫')}</div>`}</div>`}

function learn(){return `<div class="page-enter v8-compact-index">${head('学习','13 个阶段 · 90 节课程')}${section('学习阶段')}<div class="stage-grid">${db.phases.map(p=>{const done=db.lessons.filter(l=>l.phase===p.name&&state.done.includes(l.id)).length;const count=p.end-p.start+1;return `<a href="#/learn/stage/${p.id}" class="card stage-card clickable"><span class="index">${String(p.id+1).padStart(2,'0')}</span><span class="row-body"><strong>${h(p.name)}</strong><p>第 ${p.start}–${p.end} 课 · ${done} / ${count} 已掌握</p></span><span class="row-arrow">›</span></a>`}).join('')}</div>${section('学习工具')}<div class="nav-subpages"><a href="#/learn/review" class="card nav-subpage clickable"><span><h3>复习中心</h3><p>从尚未掌握的课程继续</p></span><span class="row-arrow">›</span></a><a href="#/learn/resources" class="card nav-subpage clickable"><span><h3>学习资源</h3><p>23 项 GitHub 与文档资料</p></span><span class="row-arrow">›</span></a></div></div>`}

function stagePage(id){let stage=db.phases.find(p=>p.id===Number(id));if(!stage)return notfound();const lessons=db.lessons.filter(l=>l.phase===stage.name);return `<div class="page-enter detail-width">${breadcrumb([['学习','/learn'],[stage.name]])}${back('/learn','返回学习地图')}${head(stage.name,`第 ${stage.start}–${stage.end} 课 · ${lessons.length} 节课程`)}${lessons.length?`<div class="card list-card">${lessons.map(l=>row(`/learn/lesson/${l.id}`,`第 ${l.id} 课 · ${l.title}`,l.key.slice(0,70),state.done.includes(l.id)?'已掌握':'开始学习','▤')).join('')}</div>`:`<div class="card empty"><b>此阶段暂无课程</b>原有课程数据不会删除。完成结构确认后再整体迁入。<p style="margin-top:16px">${link('/learn','返回阶段目录','class="btn btn-soft"')}</p></div>`}</div>`}
function lessonPage(id){const l=findLesson(id);if(!l)return notfound();recent('lesson',l.id);state.lastLesson=l.id;persist();const siblings=db.lessons.filter(x=>x.phase===l.phase),idx=siblings.findIndex(x=>x.id===l.id),prev=siblings[idx-1],next=siblings[idx+1];const tab=state.lessonTab||'explain';return `<div class="page-enter detail-width">${breadcrumb([['学习','/learn'],[l.phase,`/learn/stage/${db.phases.find(p=>p.name===l.phase)?.id||0}`],[`第 ${l.id} 课`]])}${back(`/learn/stage/${db.phases.find(p=>p.name===l.phase)?.id||0}`,'返回阶段课程')}${head(`第 ${l.id} 课 · ${l.title}`,l.phase,`<button type="button" class="btn btn-ghost btn-small" data-action="favorite" data-type="lesson" data-id="${l.id}">${state.favorites.includes(`lesson:${l.id}`)?'★ 已收藏':'☆ 收藏'}</button> <a class="btn btn-ghost btn-small" href="#/me/notes/${l.id}">写笔记</a>`)}<div class="card detail-card"><div class="eyebrow">KEY IDEA · 核心概念</div><p class="detail-lead">${h(l.key)}</p><div class="section-head"><h2 style="font-size:15px">学习内容</h2>${state.done.includes(l.id)?'<span class="token token-green">已掌握</span>':'<span class="token token-neutral">待学习</span>'}</div><div class="tabs" role="tablist" aria-label="课程内容">${[['explain','讲解'],['example','工厂类比'],['erp','ERP 应用'],['quiz','小测验']].map(([k,v])=>`<button role="tab" type="button" data-action="lesson-tab" data-tab="${k}" aria-selected="${tab===k}" class="${tab===k?'active':''}">${v}</button>`).join('')}</div><div id="lessonContent" class="tabcontent">${lessonTabHtml(l,tab)}</div></div><div class="lesson-footer">${prev?link(`/learn/lesson/${prev.id}`,'← 上一课','class="btn btn-ghost"'):'<span></span>'}${next?link(`/learn/lesson/${next.id}`,'下一课 →','class="btn btn-primary"'):link('/learn','返回学习地图','class="btn btn-soft"')}</div></div>`}
function lessonTabHtml(l,t){if(t==='explain')return `<p class="reading-text">${h(l.key)}\n\n${h(l.pitfall)}</p>${l.steps?.length?`<div class="section-head"><h3>理解步骤</h3></div><div class="info-list">${l.steps.map((s,i)=>`<div><dt>0${i+1}</dt><dd>${h(s)}</dd></div>`).join('')}</div>`:''}`;if(t==='example')return `<div class="callout"><b>广告加工厂类比</b><p style="margin-top:9px">${h(l.analogy)}</p></div>`;if(t==='erp')return `<div class="callout"><b>ERP 实际应用</b><p style="margin-top:9px">${h(l.erp)}</p></div>`;if(t==='quiz'){const answer=state.quiz[l.id];return `<h3 style="margin-bottom:13px">${h(l.q)}</h3><div id="quizOptions">${l.opts.map((o,i)=>`<label class="answer-option"><input type="radio" name="lessonAnswer" value="${i}" ${answer?.value===i?'checked':''}><span>${h(o)}</span></label>`).join('')}</div><div style="margin-top:15px"><button data-action="submit-quiz" data-id="${l.id}" type="button" class="btn btn-primary">提交答案</button></div>${answer?`<div class="answer-result ${answer.correct?'':'bad'}">${answer.correct?'回答正确 · 已掌握':'还未答对 · 可再次尝试'}<p>${h(l.why)}</p></div>`:''}`}return ''}
function review(){const missed=db.lessons.filter(l=>!state.done.includes(l.id));const wrong=cleanLessonIds(state.wrong||[]);return `<div class="page-enter detail-width">${breadcrumb([['学习','/learn'],['复习中心']])}${back('/learn')}${head('复习中心',`还有 ${missed.length} 节未掌握；错题 ${wrong.length} 节。`)}${wrong.length?`<div class="section-head"><h2>错题优先</h2></div><div class="card list-card">${wrong.map(id=>{const l=findLesson(id);return l?row(`/learn/lesson/${id}`,`第 ${id} 课 · ${l.title}`,'继续复习','','▤'):''}).join('')}</div>`:''}<div class="section-head"><h2>未掌握课程</h2></div><div class="card list-card">${missed.length?missed.map(l=>row(`/learn/lesson/${l.id}`,`第 ${l.id} 课 · ${l.title}`,'点击继续学习或答题','','▤')).join(''):`<div class="empty"><b>课程已全部掌握</b></div>`}</div></div>`}
function components(){const cats=Object.entries(db.componentCategories);const q=filters.component.trim().toLowerCase();const hits=q?db.components.filter(c=>[c.name,c.en,c.alias,c.desc,c.erp].join(' ').toLowerCase().includes(q)):[];return `<div class="page-enter v8-compact-index">${head('组件','按类别查找，进入详情直接体验。')}<div class="filterbar component-searchbar"><label><span class="v8-sr-only">搜索全部组件</span><input id="componentSearch" class="field" type="search" autocomplete="off" placeholder="输入名称或用途" value="${h(filters.component)}"></label><button type="button" class="btn btn-ghost" data-action="clear-components">清除</button></div><div id="componentCatalog" ${q?'hidden':''}>${section('组件分类')}<div class="v8-category-grid">${cats.map(([id,info],i)=>{const count=db.components.filter(x=>x.category===id).length;return `<a class="card v8-category-tile" href="#/components/category/${id}"><span class="v8-category-icon">${iconFor(id)}</span><div><strong>${h(info[0])}</strong><p>${h(info[1])}</p></div><span class="micro">${count}</span><span class="row-arrow">›</span></a>`}).join('')}</div>${section('设计知识')}<div class="nav-subpages"><a class="card nav-subpage" href="#/components/patterns"><span><h3>设计避坑</h3><p>14 条常见问题</p></span><span class="row-arrow">›</span></a><a class="card nav-subpage" href="#/components/sources"><span><h3>开源参考</h3><p>8 项 GitHub 资源</p></span><span class="row-arrow">›</span></a></div></div><div id="componentSearchArea" ${q?'':'hidden'}>${section('搜索结果')}<p class="micro" id="compCount">${hits.length} 个匹配组件</p><div class="card list-card" id="componentResults">${componentRows(hits)}</div></div></div>`}
function componentRows(list){return list.length?list.map(c=>row(`/components/detail/${c.id}`,`${c.name} · ${c.en}`,c.desc,db.componentCategories[c.category]?.[0]||c.category,iconFor(c.category))).join(''):`<div class="empty"><b>没有找到匹配组件</b>尝试清除筛选或搜索其他词。</div>`}
function componentDetail(id){const c=findComponent(id);if(!c)return notfound();recent('component',id);const tab=state.componentTabs[id]||'demo',category=db.componentCategories[c.category]?.[0]||c.category;return `<div class="page-enter detail-width">${breadcrumb([['组件','/components'],[category,`/components/category/${c.category}`],[c.name]])}${back(lastComponentListRoute,'返回组件列表')}${head(`${c.name} · ${c.en}`,c.desc,`<button class="btn btn-ghost btn-small" type="button" data-action="favorite" data-type="component" data-id="${c.id}">${state.favorites.includes(`component:${c.id}`)?'★ 已收藏':'☆ 收藏'}</button>`)}<div class="tabs" role="tablist" aria-label="组件详情栏目">${[['demo','演示'],['guide','说明'],['erp','ERP 场景'],['codex','Codex']].map(([k,v])=>`<button role="tab" data-action="component-tab" data-id="${c.id}" data-tab="${k}" aria-selected="${tab===k}" type="button" class="${tab===k?'active':''}">${v}</button>`).join('')}</div><div id="componentContent" style="margin-top:16px">${componentTabHtml(c,tab)}</div><div class="lesson-footer">${link('/components','← 组件目录','class="btn btn-ghost"')}${link('/practice','查看实战场景 →','class="btn btn-soft"')}</div></div>`}
function componentTabHtml(c,tab){if(tab==='demo')return `<div class="demo-panel"><div class="demo-toolbar"><strong style="font-size:14px">现场交互</strong><span class="preview-mark">仅本地模拟 · 无真实数据</span></div><div class="demo-stage" id="demoStage">${renderDemo(c)}</div></div>`;if(tab==='guide')return `<div class="card detail-card"><dl class="info-list"><div><dt>是什么</dt><dd>${h(c.desc)}</dd></div><div><dt>广告工厂类比</dt><dd>${h(c.analogy)}</dd></div><div><dt>适合使用</dt><dd>${h(c.use)}</dd></div><div><dt>避免使用</dt><dd>${h(c.avoid)}</dd></div><div><dt>容易混淆</dt><dd>${h(c.compare)}</dd></div></dl></div>`;if(tab==='erp')return `<div class="card detail-card"><div class="eyebrow">BUSINESS CONTEXT</div><h2 style="margin:12px 0">在广告加工 ERP 中怎么用</h2><p class="reading-text">${h(c.erp)}</p><div style="margin-top:25px">${link('/practice','查看 ERP 场景 →','class="btn btn-primary"')}</div></div>`;if(tab==='codex'){const p=codexPrompt(c);return `<div class="card detail-card"><div class="eyebrow">COPY TO CODEX</div><h2 style="margin:10px 0 15px">组件实现指令</h2><pre class="promptbox">${h(p)}</pre><button class="btn btn-primary" type="button" data-action="copy" data-copy="component" data-id="${c.id}">复制开发要求</button></div>`}return ''}
function codexPrompt(c){return `任务：为现有 ERP 的相关页面实现 ${c.name}（${c.en}）组件。\n业务用途：${c.erp}\n适用场景：${c.use}\n注意事项：${c.avoid}\n范围：仅修改指定页面和必要组件文件；保留其他既有逻辑。\n要求：实现真实交互反馈、必要的输入校验、加载/错误/禁用等适用状态；兼顾手机和电脑。\n验收：操作可响应、取消不保存、刷新行为符合既定规则、无控制台错误；输出修改文件清单及验证结果。`}
function categoryPage(cat){const items=db.components.filter(c=>c.category===cat);const name=db.componentCategories[cat]?.[0]||cat;return `<div class="page-enter detail-width">${breadcrumb([['组件','/components'],[name]])}${back('/components','返回组件目录')}${head(name,`此类别已接入 ${items.length} 个组件`)}<div class="card list-card">${items.length?componentRows(items):'<div class="empty">暂无组件</div>'}</div></div>`}
function renderDemo(c){let id=c.id;switch(id){
case 'modal':return `<div><div class="micro" style="margin-bottom:12px">体验打开、验证、取消与键盘焦点管理</div><button class="btn btn-primary" type="button" data-action="open-modal">打开新增客户弹窗</button></div>`;
case 'button':return `<div class="controls"><button class="btn btn-primary" data-action="demo-button" type="button">保存报价</button><button class="btn btn-ghost" data-action="demo-cancel" type="button">取消</button><button class="btn btn-primary" disabled type="button">不可用</button></div><p id="demoStatus" class="demo-output">点击按钮，查看操作反馈。</p>`;
case 'input':return `<div style="max-width:410px"><label class="demo-label" for="demoInput">客户名称</label><input class="field" id="demoInput" maxlength="30" placeholder="请输入客户名称"><div id="demoInputHelp" class="field-hint">请输入后失焦，体验必填校验。</div></div>`;
case 'select':return `<div style="max-width:400px"><label class="demo-label" for="demoSelect">产品工艺</label><select id="demoSelect" class="field"><option value="">请选择</option><option>不锈钢背发光字</option><option>无边发光字</option><option>铝单板门头</option></select><div class="demo-output" id="demoSelectStatus">尚未选择工艺</div></div>`;
case 'form':return `<form id="componentForm" style="width:100%;max-width:460px"><div class="formgrid"><label class="wide"><span class="demo-label">客户名称 *</span><input class="field" name="name" required placeholder="客户名称"></label><label class="wide"><span class="demo-label">联系电话（选填）</span><input class="field" name="phone" inputmode="tel" placeholder="联系电话"></label></div><p id="componentFormMessage" class="field-hint" aria-live="polite">必填字段未填写将阻止提交。</p><button class="btn btn-primary" style="margin-top:13px" type="submit">验证并保存模拟数据</button></form>`;
case 'drawer':return `<button class="btn btn-primary" type="button" data-action="open-drawer">查看订单详情</button><p class="micro">抽屉更适合查看需要保留上下文的较长明细。</p>`;
case 'table':return `<div class="controls"><label><span class="demo-label">查找订单</span><input id="demoTableSearch" class="field" placeholder="订单号或客户" type="search"></label><button class="btn btn-ghost btn-small" type="button" data-action="demo-sort">金额排序 ↕</button></div><div class="table-wrap" id="demoTableRows">${renderDemoTable('')}</div>`;
case 'toast':return `<div class="controls"><button class="btn btn-primary" type="button" data-action="demo-toast" data-message="模拟保存成功">显示成功提示</button><button class="btn btn-ghost" type="button" data-action="demo-toast" data-message="网络异常（模拟）">显示错误提示</button></div><div class="micro">轻提示在操作后短暂出现，不阻断当前页面。</div>`;
case 'tabs':return `<div class="seg" role="tablist"><button type="button" class="on" data-action="demo-tabs" data-tab="basic">基本信息</button><button type="button" data-action="demo-tabs" data-tab="work">生产进度</button><button type="button" data-action="demo-tabs" data-tab="pay">财务</button></div><div class="demo-output" id="demoTabsContent">订单客户：瑞冠口腔 · 交付方式：送货</div>`;
case 'switch':return `<div class="controls"><button type="button" aria-pressed="false" aria-label="自动材料匹配" class="switch" id="demoSwitch" data-action="demo-switch"><span></span></button><span id="demoSwitchText">自动材料匹配：关闭</span></div>`;
case 'checkbox':return `<label class="controls" style="gap:10px"><input type="checkbox" id="demoCheckbox" style="width:18px;height:18px;accent-color:#315dde"> <span>已确认报价图纸与尺寸</span></label><p class="demo-output" id="demoCheckStatus">尚未确认</p>`;
case 'badge':return `<div class="controls"><span class="status pending">待生产</span><span class="status">已完成</span><span class="token">审核中</span></div><p class="micro">状态标签只传达信息，不应被误认为可以点击的操作按钮。</p>`;
default:return window.V8Demos.render(c);}}
function renderDemoTable(query='',sort=false){let data=[{id:'BJ-1028',name:'瑞冠口腔',amount:1560},{id:'BJ-1029',name:'悦己瑜伽',amount:960},{id:'BJ-1030',name:'天悦广告',amount:2480}].filter(x=>(x.id+x.name).toLowerCase().includes(query.toLowerCase()));if(sort)data.sort((a,b)=>b.amount-a.amount);return `<table><thead><tr><th>订单</th><th>客户</th><th>金额</th></tr></thead><tbody>${data.length?data.map(x=>`<tr><td>${x.id}</td><td>${x.name}</td><td>¥${x.amount}</td></tr>`).join(''):'<tr><td colspan="3">没有匹配订单</td></tr>'}</tbody></table>`}
function practice(){return `<div class="page-enter">${head('ERP 实战','6 个可操作的业务场景')}<div class="card list-card">${db.scenes.map(s=>row(`/practice/scenario/${s.id}`,s.title,s.desc,s.tag||'实战','▧')).join('')}</div>${section('组合方案')}<div class="card list-card">${db.templates.map(s=>row(`/practice/scenario/${s.id}`,s.name,s.why,'示例','▧')).join('')}</div></div>`}

function scenePage(id){const s=findScene(id);if(!s)return notfound();recent('scene',id);return `<div class="page-enter detail-width">${breadcrumb([['实战','/practice'],[s.title]])}${back('/practice','返回场景目录')}${head(s.title,s.desc,`<span class="preview-mark">仅本地模拟</span>`)}<div class="demo-panel"><div class="demo-toolbar"><strong>业务演示</strong><span class="micro">独立样本数据 · 不提交 ERP</span></div><div class="demo-stage" id="sceneStage">${renderScene(s)}</div></div><details class="v8-details" style="margin-top:18px"><summary>场景说明与验收标准</summary><p>${h(s.why||'')}</p><p>${h(s.accept||'')}</p></details>${section('关联组件')}<div class="card list-card">${(s.id==='customers'?['input','form','table','modal']:s.id==='quotes'?['select','input','form']:s.id==='production'?['kanban-board','timeline','badge']:s.id==='stock'?['number-input','table','validation']:s.id==='payroll'?['currency','table','statistic']:['table','badge']).map(id=>{const c=findComponent(id);return c?row(`/components/detail/${c.id}`,`${c.name} · ${c.en}`,c.erp,'查看 Demo',iconFor(c.category)):''}).join('')}</div></div>`}
function renderScene(s){if(s.id==='customers'){let fields=state.sceneForms.customers||{name:'',phone:''};return `<form id="sceneCustomerForm"><div class="formgrid"><label><span class="demo-label">客户名称 *</span><input class="field" name="name" required maxlength="30" placeholder="请输入客户名称" value="${h(fields.name)}"></label><label><span class="demo-label">联系电话</span><input class="field" name="phone" inputmode="tel" placeholder="可不填" value="${h(fields.phone)}"></label></div><div class="controls" style="margin:12px 0"><button type="submit" class="btn btn-primary">模拟新增客户</button><button class="btn btn-ghost" type="button" data-action="clear-customer-form">清空输入</button></div><div id="sceneCustomerFeedback" class="field-hint" aria-live="polite">提交前检查必填项。数据只在本预览浏览器内保存。</div></form><div class="table-wrap" id="sceneCustomersTable">${renderCustomerTable()}</div>`}
if(s.id==='quotes'){let f=state.sceneForms.quotes||baseState.sceneForms.quotes;return `<form id="sceneQuoteForm"><div class="formgrid"><label class="wide"><span class="demo-label">产品工艺</span><select name="name" class="field"><option ${f.name==='无边发光字'?'selected':''}>无边发光字</option><option ${f.name==='不锈钢背发光字'?'selected':''}>不锈钢背发光字</option></select></label><label><span class="demo-label">宽（cm）</span><input name="width" type="number" min="1" max="10000" class="field" value="${h(f.width)}"></label><label><span class="demo-label">高（cm）</span><input name="height" type="number" min="1" max="10000" class="field" value="${h(f.height)}"></label><label><span class="demo-label">数量</span><input name="qty" type="number" min="1" max="10000" class="field" value="${h(f.qty)}"></label><label><span class="demo-label">示例面积单价（元/㎡）</span><input name="price" type="number" min="0.01" step="0.01" class="field" value="${h(f.price)}"></label></div><div style="margin-top:13px"><button class="btn btn-primary" type="submit">计算示例金额</button></div></form><div class="demo-output" id="quoteResult">仅演示界面校验与公式计算，不代表公司真实报价规则。</div>`}
if(s.id==='production')return `<div class="v8-scene-flow"><div class="controls"><label>选择订单 <select class="field" id="productionOrder">${state.sceneProduction.map(x=>`<option value="${h(x.id)}">${h(x.id)} · ${h(x.name)}</option>`).join('')}</select></label><label>更新状态 <select id="productionStatus" class="field"><option>待排版</option><option>生产中</option><option>已完成</option></select></label><button type="button" class="btn btn-primary" data-action="scene-production-update">保存模拟状态</button></div><div id="productionMsg" class="demo-output">请选择订单及状态</div><div class="table-wrap">${renderProductionTable()}</div></div>`;
if(s.id==='stock')return `<div class="v8-scene-flow"><div class="controls"><label>材料 <select class="field" id="stockItem">${state.sceneStock.map((x,i)=>`<option value="${i}">${h(x.name)}</option>`).join('')}</select></label><label>变动数量 <input id="stockDelta" class="field" type="number" step="1" value="2"></label><button class="btn btn-primary" type="button" data-action="scene-stock-update">模拟入出库</button></div><div id="stockMessage" class="demo-output">正数入库，负数出库。库存不得小于 0。</div><div class="table-wrap">${renderStockTable()}</div></div>`;
if(s.id==='payroll')return `<div class="v8-scene-flow"><div class="formgrid"><label>完成数量 <input class="field" id="payrollQty" type="number" min="0" step="1" value="10"></label><label>单件计件金额（元） <input class="field" id="payrollRate" type="number" min="0" step="0.01" value="6.50"></label></div><div class="controls" style="margin-top:12px"><button class="btn btn-primary" type="button" data-action="scene-payroll-calc">核对计件金额</button></div><div class="demo-output" id="payrollResult">模拟计件：数量 × 单价，不连接正式工资数据。</div></div>`;
return `<div class="controls"><input class="field" id="sceneOrderSearch" type="search" placeholder="搜索订单号或客户" style="flex:1;min-width:140px" value="${h(filters.orderQuery)}"><select class="field" id="sceneOrderStatus" style="max-width:145px"><option value="all" ${filters.orders==='all'?'selected':''}>全部状态</option><option value="待生产" ${filters.orders==='待生产'?'selected':''}>待生产</option><option value="生产中" ${filters.orders==='生产中'?'selected':''}>生产中</option><option value="已完成" ${filters.orders==='已完成'?'selected':''}>已完成</option></select></div><div class="table-wrap" id="sceneOrdersTable">${renderOrdersTable()}</div>`}
function renderProductionTable(){return `<table><thead><tr><th>订单</th><th>客户</th><th>生产状态</th></tr></thead><tbody>${state.sceneProduction.map(x=>`<tr><td>${h(x.id)}</td><td>${h(x.name)}</td><td>${h(x.status)}</td></tr>`).join('')}</tbody></table>`}
function renderStockTable(){return `<table><thead><tr><th>材料</th><th>库存</th></tr></thead><tbody>${state.sceneStock.map(x=>`<tr><td>${h(x.name)}</td><td>${h(x.qty)}</td></tr>`).join('')}</tbody></table>`}
function renderCustomerTable(){return state.sceneCustomers.length?`<table><thead><tr><th>客户</th><th>联系电话</th></tr></thead><tbody>${state.sceneCustomers.map(x=>`<tr><td>${h(x.name)}</td><td>${h(x.phone||'—')}</td></tr>`).join('')}</tbody></table>`:'<div class="empty">当前还没有模拟客户。填写上面的表单试试。</div>'}
function renderOrdersTable(){let data=state.sceneOrders.filter(x=>(filters.orders==='all'||x.status===filters.orders)&&[x.id,x.customer].join(' ').toLowerCase().includes(filters.orderQuery.toLowerCase()));return `<table><thead><tr><th>订单号</th><th>客户</th><th>状态</th><th>金额</th></tr></thead><tbody>${data.length?data.map(x=>`<tr><td>${h(x.id)}</td><td>${h(x.customer)}</td><td><span class="status ${x.status==='待生产'?'pending':''}">${h(x.status)}</span></td><td>${h(x.amount)}</td></tr>`).join(''):'<tr><td colspan="4">暂无符合条件的订单</td></tr>'}</tbody></table>`}
function me(){const favoriteCount=state.favorites.length,notesCount=Object.values(state.notes).filter(x=>String(x).trim()).length;return `<div class="page-enter">${head('我的工作台','收藏、笔记和数据设置集中收纳，不占用学习页面。')}<div class="home-hero"><div class="card detail-card"><div class="eyebrow">YOUR SPACE</div><div style="display:flex;gap:30px;margin:22px 0"><div><h2>${state.done.length}</h2><span class="micro">已掌握课程</span></div><div><h2>${favoriteCount}</h2><span class="micro">已收藏内容</span></div><div><h2>${notesCount}</h2><span class="micro">笔记</span></div></div><p class="inline-help">当前数据仅保存在本机浏览器。</p></div><div class="card detail-card"><h3>快速继续</h3><p class="muted" style="font-size:13px;margin:9px 0 18px">回到最近学习的课程。</p>${link(`/learn/lesson/${state.lastLesson||49}`,'继续学习 →','class="btn btn-primary"')}</div></div>${section('管理与收藏')}<div class="card list-card">${row('/me/favorites','我的收藏',`${favoriteCount} 个知识条目`,'','☆')}${row('/me/notes','学习笔记',`${notesCount} 篇笔记`,'','▤')}${row('/me/data','数据备份与设置','导出或导入原型测试记录','','⇆')}</div></div>`}
function favorites(){return `<div class="page-enter detail-width">${breadcrumb([['我的','/me'],['收藏']])}${back('/me')}${head('我的收藏',`共 ${state.favorites.length} 个条目`)}<div class="card list-card">${state.favorites.length?state.favorites.map(x=>{const [type,id]=x.split(':');if(type==='lesson'){let l=findLesson(id);return l?row(`/learn/lesson/${id}`,l.title,'课程', '', '▤'):''}const c=findComponent(id);return c?row(`/components/detail/${id}`,`${c.name} · ${c.en}`,'组件','','◫'):''}).join(''):'<div class="empty"><b>还没有收藏</b>在课程或组件详情右上角点击“收藏”。</div>'}</div></div>`}
function notes(){const saved=db.lessons.filter(l=>state.notes[l.id]&&String(state.notes[l.id]).trim());return `<div class="page-enter detail-width">${breadcrumb([['我的','/me'],['学习笔记']])}${back('/me')}${head('学习笔记',`${saved.length} 篇笔记`)}<div class="card list-card">${saved.length?saved.map(l=>row(`/me/notes/${l.id}`,`第 ${l.id} 课 · ${l.title}`,state.notes[l.id].slice(0,70),'','▤')).join(''):'<div class="empty"><b>暂无笔记</b>进入任意课程，选择“写笔记”。</div>'}</div></div>`}
function noteDetail(id){const l=findLesson(id);if(!l)return notfound();return `<div class="page-enter detail-width">${breadcrumb([['我的','/me'],['笔记','/me/notes'],[l.title]])}${back('/me/notes')}${head(`学习笔记 · 第 ${id} 课`,l.title)}<div class="card detail-card"><label class="demo-label" for="noteText">自己的理解与问题</label><textarea id="noteText" class="field" rows="9" placeholder="写下你对这节课的理解……" style="resize:vertical;min-height:180px">${h(state.notes[id]||'')}</textarea><div class="lesson-footer"><span class="micro">输入后自动保存</span>${link(`/learn/lesson/${id}`,'回到课程 →','class="btn btn-soft"')}</div></div></div>`}
function dataPage(){return `<div class="page-enter detail-width">${breadcrumb([['我的','/me'],['数据与设置']])}${back('/me')}${head('数据与设置','预览数据独立保存，不影响正式版。')}<div class="card detail-card stack"><div><h3>从 V4 正式版复制进度</h3><p class="inline-help" style="margin:5px 0 12px">仅读取同一浏览器内的正式版记录。合并到本预览，不修改正式版。不同设备请使用 JSON 导入。</p><div class="controls"><button type="button" class="btn btn-primary" data-action="import-official">检测并复制正式版记录</button><button type="button" class="btn btn-ghost" data-action="restore-before-migration">撤销最近一次合并</button></div></div><hr style="border:0;border-top:1px solid var(--line);width:100%"><div><h3>导出学习进度</h3><p class="inline-help" style="margin:5px 0 14px">包含进度、收藏、笔记及模拟记录。</p><button type="button" class="btn btn-primary" data-action="export">导出备份</button></div><hr style="border:0;border-top:1px solid var(--line);width:100%"><div><h3>导入学习记录</h3><p class="inline-help" style="margin:5px 0 12px">支持 V8 备份；也可手动导入 V4/V7 导出的学习进度备份。</p><label class="btn btn-ghost" style="cursor:pointer" for="importFile">选择备份文件</label><input type="file" accept=".json,application/json" id="importFile" hidden></div><hr style="border:0;border-top:1px solid var(--line);width:100%"><div><h3>清空预览记录</h3><p class="inline-help" style="margin:5px 0 12px">仅清除本预览记录。</p><button type="button" class="btn btn-ghost" data-action="reset-preview">清空预览数据</button></div></div></div>`}
function searchPage(){const q=filters.global.trim().toLowerCase();let entries=[...db.lessons.map(l=>({title:`第 ${l.id} 课 · ${l.title}`,sub:l.key,url:`/learn/lesson/${l.id}`,type:'课程',index:`${l.title} ${l.key} ${l.phase}`})),...db.components.map(c=>({title:`${c.name} · ${c.en}`,sub:c.desc,url:`/components/detail/${c.id}`,type:'组件',index:`${c.name} ${c.en} ${c.alias} ${c.erp}`})),...db.scenes.map(s=>({title:s.title,sub:s.desc,url:`/practice/scenario/${s.id}`,type:'实战',index:`${s.title} ${s.desc}`}))];let r=q?entries.filter(x=>x.index.toLowerCase().includes(q)).slice(0,30):[];return `<div class="page-enter detail-width">${breadcrumb([['总览','/home'],['全局搜索']])}${back('/home')}${head('全局搜索','搜索课程、组件及 ERP 场景。')}<label><span class="micro">搜索词</span><input id="fullSearch" type="search" class="field" placeholder="例如数据库、Modal、报价" autocomplete="off" value="${h(filters.global)}"></label><div class="section-head"><h2>${q?'搜索结果':'快捷入口'}</h2><span class="micro" id="searchCount">${r.length} 条</span></div><div class="card list-card" id="globalSearchResults">${q?(r.length?r.map(x=>row(x.url,x.title,x.sub.slice(0,80),x.type,'⌕')).join(''):'<div class="empty">没有找到结果。试试其他词。</div>'):`${row('/learn','课程学习','全部 90 节课程')}${row('/components','组件实验室','全部 88 个组件')}${row('/practice','ERP 实战','交互业务场景')}`}</div></div>`}
function resources(){return `<div class="page-enter detail-width">${breadcrumb([['学习','/learn'],['学习资源']])}${back('/learn')}${head('学习资源',`${db.resources.length} 项开源与官方资料`)}<div class="card list-card">${db.resources.map(x=>`<a class="list-row" href="${h(x.url)}" target="_blank" rel="noopener noreferrer"><span class="row-icon">↗</span><span class="row-body"><span class="row-title">${h(x.name)}</span><span class="row-desc">${h(x.desc)}</span></span></a>`).join('')}</div></div>`}
function patterns(){return `<div class="page-enter detail-width">${breadcrumb([['组件','/components'],['设计避坑']])}${back('/components')}${head('设计避坑','14 条常见错误与改进方向')}<div class="card list-card">${db.anti.map((x,i)=>`<div class="v8-pattern"><span>${String(i+1).padStart(2,'0')}</span><p>${h(Array.isArray(x)?x.join(' → '):x)}</p></div>`).join('')}</div></div>`}
function sources(){return `<div class="page-enter detail-width">${breadcrumb([['组件','/components'],['开源参考']])}${back('/components')}${head('开源参考','GitHub 项目与组件文档')}<div class="card list-card">${db.sources.map(x=>`<a class="list-row" href="${h(x.url)}" target="_blank" rel="noopener noreferrer"><span class="row-icon">↗</span><span class="row-body"><span class="row-title">${h(x.name)}</span><span class="row-desc">${h(x.role)}</span></span></a>`).join('')}</div></div>`}
function notfound(){return `<div class="page-enter detail-width">${head('页面不存在','请检查链接地址。')}<div class="card detail-card">${link('/home','返回工作台','class="btn btn-primary"')}</div></div>`}
function render(){route=path();let segments=route.split('/').filter(Boolean),type=segments[0]||'home';let html=type==='home'?home():type==='learn'?(segments[1]==='stage'?stagePage(segments[2]):segments[1]==='lesson'?lessonPage(segments[2]):segments[1]==='review'?review():segments[1]==='resources'?resources():learn()):type==='components'?(segments[1]==='detail'?componentDetail(segments[2]):segments[1]==='category'?categoryPage(segments[2]):segments[1]==='patterns'?patterns():segments[1]==='sources'?sources():components()):type==='practice'?(segments[1]==='scenario'?scenePage(segments[2]):practice()):type==='me'?(segments[1]==='favorites'?favorites():segments[1]==='notes'?(segments[2]?noteDetail(segments[2]):notes()):segments[1]==='data'?dataPage():me()):type==='search'?searchPage():notfound();$('#view').innerHTML=html;document.querySelectorAll('[data-nav]').forEach(a=>{let active=a.dataset.nav===type;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});document.title=type==='home'?'学习工作台 V8 · 手机适配审查版':($('#view h1')?.textContent||'学习工作台')+' · V8 手机适配审查版';}
function changeRoute(){if(priorRoute)routeY[priorRoute]=window.scrollY;render();const y=routeY[route]??0;requestAnimationFrame(()=>window.scrollTo(0,y));priorRoute=route}
function trapOverlay(el,opener){if(activeOverlay)closeOverlay(false);activeOverlay=el;overlayTrigger=opener||document.activeElement;$('#overlayRoot').replaceChildren(el);$('#shell').inert=true;document.addEventListener('keydown',overlayKey,true);let first=focusables(el)[0];if(first)first.focus()}
function focusables(el){return [...el.querySelectorAll('button:not([disabled]),a[href],input:not([disabled]),select:not([disabled]),textarea:not([disabled]),[tabindex]:not([tabindex="-1"])')].filter(e=>e.offsetParent!==null||e.getClientRects().length>0)}
function overlayKey(e){if(!activeOverlay)return;if(e.key==='Escape'){e.preventDefault();e.stopPropagation();closeOverlay();return}if(e.key==='Tab'){let list=focusables(activeOverlay);if(!list.length){e.preventDefault();return}let cur=list.indexOf(document.activeElement);if(e.shiftKey&&(cur===0||cur===-1)){e.preventDefault();list[list.length-1].focus()}else if(!e.shiftKey&&(cur===list.length-1||cur===-1)){e.preventDefault();list[0].focus()}}}
function closeOverlay(refocus=true){if(!activeOverlay)return;const tr=overlayTrigger;$('#shell').inert=false;$('#overlayRoot').replaceChildren();activeOverlay=null;overlayTrigger=null;document.removeEventListener('keydown',overlayKey,true);if(refocus&&tr&&tr.isConnected)tr.focus()}
function openModal(trigger){const wrap=document.createElement('div');wrap.className='modal-mask';wrap.innerHTML=`<div role="dialog" aria-modal="true" aria-labelledby="modalTitle" class="modal-dialog"><button class="modal-close" type="button" aria-label="关闭弹窗" data-action="close-overlay">×</button><h2 id="modalTitle">新增客户 · Demo</h2><p>校验必填项后模拟保存，不会进入真实 ERP。</p><form id="modalDemoForm" style="margin-top:18px"><label class="demo-label" for="modalName">客户名称 *</label><input class="field" id="modalName" name="name" required placeholder="例如瑞冠口腔"><div class="field-hint" id="modalHint" aria-live="polite">请填写客户名称。</div><div class="modal-footer"><button type="button" class="btn btn-ghost" data-action="close-overlay">取消</button><button type="submit" class="btn btn-primary">模拟保存</button></div></form></div>`;wrap.addEventListener('click',e=>{if(e.target===wrap)closeOverlay()});trapOverlay(wrap,trigger)}
function openDrawer(trigger){const wrap=document.createElement('div');wrap.className='drawer-wrap';wrap.innerHTML=`<aside role="dialog" aria-modal="true" aria-labelledby="drawerTitle" class="drawer"><div style="display:flex;justify-content:space-between;align-items:center"><h2 id="drawerTitle">订单明细 · A-1028</h2><button class="btn btn-ghost btn-small" data-action="close-overlay">关闭 ×</button></div><p class="inline-help" style="margin:12px 0 20px">此内容为演示记录，不影响真实订单。</p><dl class="info-list"><div><dt>客户</dt><dd>瑞冠口腔</dd></div><div><dt>品类</dt><dd>不锈钢背发光字</dd></div><div><dt>工序</dt><dd>排版 → 切割 → 焊接 → 组装</dd></div><div><dt>当前状态</dt><dd><span class="status pending">待生产</span></dd></div></dl></aside>`;wrap.addEventListener('click',e=>{if(e.target===wrap)closeOverlay()});trapOverlay(wrap,trigger)}
function showReset(trigger){const wrap=document.createElement('div');wrap.className='modal-mask';wrap.innerHTML=`<div role="dialog" aria-modal="true" aria-labelledby="confirmTitle" class="modal-dialog"><h2 id="confirmTitle">清空 V8 测试记录？</h2><p>仅清除这个预览的测试进度、收藏和笔记。操作不可撤销。</p><div class="modal-footer"><button class="btn btn-ghost" type="button" data-action="close-overlay">取消</button><button class="btn btn-danger" type="button" data-action="confirm-reset">确认清空</button></div></div>`;trapOverlay(wrap,trigger)}
function globalSearchPopup(trigger){nav('/search');requestAnimationFrame(()=>$('#fullSearch')?.focus())}
function submitQuiz(id){id=Number(id);let l=findLesson(id);const selected=$('input[name="lessonAnswer"]:checked');if(!selected){notify('请先选择答案');return}let val=Number(selected.value),correct=val===l.a;state.quiz[id]={value:val,correct};if(correct){if(!state.done.includes(id))state.done.push(id);state.wrong=cleanLessonIds((state.wrong||[]).filter(x=>x!==id));state.review=cleanLessonIds((state.review||[]).filter(x=>x!==id))}else{state.done=cleanLessonIds(state.done.filter(x=>x!==id));state.wrong=cleanLessonIds([...(state.wrong||[]),id]);state.review=cleanLessonIds([...(state.review||[]),id])}persist();const tab=$('#lessonContent');if(tab)tab.innerHTML=lessonTabHtml(l,'quiz');notify(correct?'回答正确，已标记为掌握':'回答不正确，可以再次尝试')}
function demoAction(t){const a=t.dataset.action,id=t.dataset.id;if(a==='lesson-tab'){state.lessonTab=t.dataset.tab;persist();const l=findLesson(route.split('/')[3]);if(l){$('#lessonContent').innerHTML=lessonTabHtml(l,state.lessonTab);document.querySelectorAll('[data-action="lesson-tab"]').forEach(b=>{let on=b.dataset.tab===state.lessonTab;b.classList.toggle('active',on);b.setAttribute('aria-selected',String(on))})}return}
if(a==='component-tab'){state.componentTabs[id]=t.dataset.tab;persist();const c=findComponent(id);if(c){$('#componentContent').innerHTML=componentTabHtml(c,t.dataset.tab);document.querySelectorAll('[data-action="component-tab"]').forEach(b=>{let on=b.dataset.tab===t.dataset.tab;b.classList.toggle('active',on);b.setAttribute('aria-selected',String(on))})}return}
if(a==='favorite'){let k=t.dataset.type+':'+id;state.favorites=state.favorites.includes(k)?state.favorites.filter(x=>x!==k):[...state.favorites,k];persist();t.textContent=state.favorites.includes(k)?'★ 已收藏':'☆ 收藏';return}
if(a==='clear-components'){filters.component='';filters.componentCat='all';render();return}
if(a==='component-cat'){filters.componentCat=t.dataset.cat;updateComponents();return}
if(a==='submit-quiz'){submitQuiz(id);return}
if(a==='open-modal'){openModal(t);return}if(a==='open-drawer'){openDrawer(t);return}if(a==='close-overlay'){closeOverlay();return}
if(a==='demo-button'){let el=$('#demoStatus');if(el)el.textContent='模拟报价已保存 · 仅本地反馈';notify('模拟保存成功');return}
if(a==='demo-cancel'){let el=$('#demoStatus');if(el)el.textContent='已取消，没有保存';return}
if(a==='demo-sort'){t.dataset.reverse=t.dataset.reverse==='true'?'false':'true';$('#demoTableRows').innerHTML=renderDemoTable($('#demoTableSearch')?.value||'',t.dataset.reverse==='true');return}
if(a==='demo-toast'){notify(t.dataset.message);return}
if(a==='demo-tabs'){document.querySelectorAll('[data-action="demo-tabs"]').forEach(b=>b.classList.toggle('on',b===t));const x={basic:'订单客户：瑞冠口腔 · 交付方式：送货',work:'生产状态：待排版 · 负责人未分配',pay:'收款状态：未收款 · 示例金额 ¥1,560'};$('#demoTabsContent').textContent=x[t.dataset.tab];return}
if(a==='demo-switch'){let on=t.getAttribute('aria-pressed')!=='true';t.setAttribute('aria-pressed',String(on));t.classList.toggle('on',on);$('#demoSwitchText').textContent='自动材料匹配：'+(on?'开启':'关闭');return}
if(a==='scene-production-update'){const id=$('#productionOrder')?.value,st=$('#productionStatus')?.value,obj=state.sceneProduction.find(x=>x.id===id);if(obj&&st){obj.status=st;persist();$('#productionMsg').textContent=`已更新 ${id} 为 ${st}（模拟）`;$('#sceneStage .table-wrap').innerHTML=renderProductionTable()}return}
if(a==='scene-stock-update'){const idx=Number($('#stockItem')?.value),delta=Number($('#stockDelta')?.value),item=state.sceneStock[idx];if(!item||!Number.isInteger(delta)||Math.abs(delta)>100000||item.qty+delta<0){$('#stockMessage').textContent='无效数量或库存不足，操作未执行';return}item.qty+=delta;persist();$('#stockMessage').textContent=`${item.name} 库存更新为 ${item.qty}`;$('#sceneStage .table-wrap').innerHTML=renderStockTable();return}
if(a==='scene-payroll-calc'){const qty=Number($('#payrollQty')?.value),rate=Number($('#payrollRate')?.value);if(!Number.isInteger(qty)||qty<0||qty>100000||!Number.isFinite(rate)||rate<0||rate>100000){$('#payrollResult').textContent='请输入有效的非负数量和单价';return}$('#payrollResult').textContent=`模拟计件金额：${qty} × ¥${rate.toFixed(2)} = ¥${(qty*rate).toFixed(2)}`;return}
if(a==='clear-customer-form'){state.sceneForms.customers={name:'',phone:''};persist();$('#sceneStage').innerHTML=renderScene(findScene('customers'));return}
if(a==='copy'){let c=findComponent(id);copyText(codexPrompt(c));return}
if(a==='import-official'){importOfficialProgress();return}
if(a==='restore-before-migration'){restoreBeforeMigration();return}
if(a==='export'){const payload={format:'adFactoryLearning.v8.full.preview',version:2,exportedAt:new Date().toISOString(),data:state};const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const el=document.createElement('a');el.href=url;el.download='V8-学习预览备份.json';document.body.append(el);el.click();el.remove();setTimeout(()=>URL.revokeObjectURL(url),500);notify('已导出备份文件');return}
if(a==='reset-preview'){showReset(t);return}
if(a==='confirm-reset'){state=structuredCloneSafe(baseState);persist();closeOverlay(false);filters={...filters,lesson:'',component:'',componentCat:'all'};nav('/home');notify('仅 V8 测试数据已清空');return}
}
async function copyText(text){try{await navigator.clipboard.writeText(text);notify('已复制 Codex 指令')}catch(e){try{const el=document.createElement('textarea');el.value=text;document.body.append(el);el.select();document.execCommand('copy');el.remove();notify('已复制')}catch(e2){notify('当前浏览器无法复制，请手动选择文本')}}}
function updateComponents(){if(route!=='/components')return;const q=filters.component.trim().toLowerCase();const hits=q?db.components.filter(c=>[c.name,c.en,c.alias,c.desc,c.erp].join(' ').toLowerCase().includes(q)):[];const catalog=$('#componentCatalog'),search=$('#componentSearchArea');if(catalog)catalog.hidden=!!q;if(search)search.hidden=!q;if(q){$('#componentResults').innerHTML=componentRows(hits);$('#compCount').textContent=hits.length+' 个匹配组件'}}
function updateSearchResults(){if(route!=='/search')return;const q=filters.global.trim().toLowerCase();let entries=[...db.lessons.map(l=>({title:`第 ${l.id} 课 · ${l.title}`,sub:l.key,url:`/learn/lesson/${l.id}`,type:'课程',index:`${l.title} ${l.key} ${l.phase}`})),...db.components.map(c=>({title:`${c.name} · ${c.en}`,sub:c.desc,url:`/components/detail/${c.id}`,type:'组件',index:`${c.name} ${c.en} ${c.alias} ${c.erp}`})),...db.scenes.map(s=>({title:s.title,sub:s.desc,url:`/practice/scenario/${s.id}`,type:'实战',index:`${s.title} ${s.desc}`}))];let arr=q?entries.filter(x=>x.index.toLowerCase().includes(q)):[];$('#searchCount').textContent=arr.length+' 条';$('#globalSearchResults').innerHTML=q?(arr.length?arr.map(x=>row(x.url,x.title,x.sub.slice(0,80),x.type,'⌕')).join(''):'<div class="empty">没有找到结果。试试其他词。</div>'):row('/learn','课程学习','当前样本课程')+row('/components','组件实验室','当前样本组件')+row('/practice','ERP 实战','交互业务场景')}
function handleClicks(e){if(window.V8Demos.handleClick(e))return;const goto=e.target.closest('[data-go]');if(goto){nav(goto.dataset.go);return}const a=e.target.closest('[data-action]');if(a){e.preventDefault();demoAction(a);return}const anchor=e.target.closest('a[href^="#/"]');if(anchor){e.preventDefault();routeY[route]=window.scrollY;const to=anchor.getAttribute('href').slice(1);if(to.startsWith('/components/detail/')&&(route==='/components'||route.startsWith('/components/category/')||route==='/search'))lastComponentListRoute=route;nav(to)}}
function handleInput(e){window.V8Demos.handleInput(e);const t=e.target;if(t.id==='componentSearch'){filters.component=t.value;updateComponents()}else if(t.id==='fullSearch'){filters.global=t.value;updateSearchResults()}else if(t.id==='demoTableSearch'){$('#demoTableRows').innerHTML=renderDemoTable(t.value,document.querySelector('[data-action="demo-sort"]')?.dataset.reverse==='true')}
else if(t.id==='sceneOrderSearch'){filters.orderQuery=t.value;$('#sceneOrdersTable').innerHTML=renderOrdersTable()}
else if(t.id==='sceneOrderStatus'){filters.orders=t.value;$('#sceneOrdersTable').innerHTML=renderOrdersTable()}
else if(t.id==='demoInput'){let b=$('#demoInputHelp');if(b){b.textContent=t.value.trim()?'已填写：'+t.value:'此字段不能为空';b.classList.toggle('error',!t.value.trim())}t.classList.toggle('field-error',!t.value.trim())}
else if(t.id==='demoSelect'){$('#demoSelectStatus').textContent=t.value?'已选择：'+t.value:'尚未选择工艺'}
else if(t.id==='demoCheckbox'){$('#demoCheckStatus').textContent=t.checked?'已确认，可以继续下一步':'尚未确认'}
else if(t.id==='noteText'){let id=Number(route.split('/').at(-1));state.notes[id]=t.value;persist()}
else if(t.closest('#sceneCustomerForm')){let f=state.sceneForms.customers||{};f[t.name]=t.value;state.sceneForms.customers=f;persist()}
else if(t.closest('#sceneQuoteForm')){let f=state.sceneForms.quotes||{};f[t.name]=t.value;state.sceneForms.quotes=f;persist()}
}
function submitForm(e){const form=e.target;if(!['modalDemoForm','componentForm','sceneCustomerForm','sceneQuoteForm'].includes(form.id))return;e.preventDefault();const fd=Object.fromEntries(new FormData(form).entries());if(form.id==='modalDemoForm'){if(!fd.name?.trim()){const hint=$('#modalHint');hint.textContent='客户名称为必填项';hint.classList.add('error');$('#modalName').focus();return}closeOverlay();notify(`已模拟创建客户：${fd.name.trim()}`);return}
if(form.id==='componentForm'){if(!fd.name?.trim()){$('#componentFormMessage').textContent='请输入客户名称';$('#componentFormMessage').classList.add('error');return}$('#componentFormMessage').textContent='已通过校验，模拟客户已保存';$('#componentFormMessage').classList.remove('error');notify('模拟保存成功');return}
if(form.id==='sceneCustomerForm'){if(!fd.name?.trim()){notify('客户名称不能为空');return}state.sceneCustomers.unshift({name:fd.name.trim(),phone:fd.phone?.trim()||''});state.sceneForms.customers={name:'',phone:''};persist();$('#sceneStage').innerHTML=renderScene(findScene('customers'));$('#sceneCustomerFeedback').textContent='已新增一条模拟客户记录';notify('已新增模拟客户');return}
if(form.id==='sceneQuoteForm'){const w=Number(fd.width),hh=Number(fd.height),qty=Number(fd.qty),price=Number(fd.price);if([w,hh,qty,price].some(v=>!Number.isFinite(v)||v<=0)||qty>10000||w>10000||hh>10000){$('#quoteResult').textContent='请输入有效的正数尺寸、数量与示例单价';notify('请输入有效的报价参数');return}const area=w*hh/10000;const total=area*qty*price;$('#quoteResult').textContent=`示例计算：${area.toFixed(4)} ㎡ × ${qty} × ¥${price.toFixed(2)} = ¥${total.toFixed(2)}。仅说明表单和面积公式，不代表广告字的实际计价方式。`;return}}
async function handleImport(e){if(e.target.id!=='importFile')return;const file=e.target.files[0];if(!file)return;try{if(file.size>3*1024*1024)throw Error('文件超过 3MB');const j=JSON.parse(await file.text());let next;
if(j.format==='ad-factory-learning-progress'&&j.version===2&&j.state&&Array.isArray(j.state.done)){
const old=j.state;next={...structuredCloneSafe(baseState),done:old.done.filter(x=>Number.isInteger(x)&&x>=1&&x<=90),notes:Object.fromEntries(Object.entries(old.notes||{}).filter(([k,v])=>/^\d+$/.test(k)&&typeof v==='string')),lastLesson:old.lastLesson||49,favorites:(old.bookmarks||[]).filter(x=>Number.isInteger(x)&&x>=1&&x<=90).map(x=>'lesson:'+x),wrong:cleanLessonIds(old.wrong),review:cleanLessonIds(old.review),quiz:Object.fromEntries(Object.entries(old.quiz||{}).filter(([k,v])=>Number.isInteger(Number(k))&&Number(k)>=1&&Number(k)<=90).map(([k,v])=>[k,{value:Number(v),correct:(db.lessons.find(l=>l.id===Number(k))?.a===Number(v))}]))};
}else if(j.format==='adFactoryLearning.v8.full.preview'&&j.version===2&&j.data){next={...structuredCloneSafe(baseState),...j.data}}else if(j.format==='adFactoryLearning.v8.skeleton'&&j.version===1&&j.data){next={...structuredCloneSafe(baseState),...j.data}}else throw Error('不支持此备份格式');
if(!Array.isArray(next.done)||!Array.isArray(next.favorites)||!next.notes||typeof next.notes!=='object')throw Error('备份数据结构异常');if(!confirm('导入会覆盖此预览中已有的学习记录。确认导入？'))return;state=next;persist();nav('/me');notify('学习记录已导入到预览版')}catch(err){notify('导入失败：'+err.message)}finally{e.target.value=''}}
function keyHandler(e){if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName)&&!activeOverlay){e.preventDefault();nav('/search');requestAnimationFrame(()=>$('#fullSearch')?.focus())}}
async function boot(){try{const response=await fetch('./data.json',{cache:'no-store'});if(!response.ok)throw Error(`HTTP ${response.status}`);db=await response.json();if(!Array.isArray(db.lessons)||!Array.isArray(db.components))throw Error('无效数据');$('#globalSearch').addEventListener('click',e=>globalSearchPopup(e.currentTarget));$('#topFavorite').addEventListener('click',()=>nav('/me/favorites'));document.addEventListener('click',handleClicks);document.addEventListener('input',handleInput);document.addEventListener('change',handleInput);document.addEventListener('submit',submitForm);document.addEventListener('change',handleImport);document.addEventListener('keydown',keyHandler);window.addEventListener('hashchange',changeRoute);if(!location.hash)location.hash='#/home';else changeRoute()}catch(err){console.error('V8 initialize failed',err);$('#view').innerHTML=`<div class="page-enter">${head('预览加载失败','无法读取课程与组件样本。')}<div class="card detail-card"><p>请通过 GitHub Pages HTTPS 地址打开本项目；本地文件预览可能阻止加载 JSON 数据。</p><p style="margin-top:12px" class="micro">${h(err.message)}</p></div></div>`}}
boot();
})();
